message.content:
{
  "description": "The creature is a large quadrupedal mammal shown in right-facing profile against a plain off-white background. It has a stocky, bear-like body covered in dense, shaggy fur that is dark brown on the back, head and outer legs and creamy off-white on the chest, throat and underside. It stands on four thick legs ending in clawed paws and has a short stubby tail at the rear. The head is bear-like with a tapered muzzle and black nose. Integrated into the fur are numerous glossy, hard, dark brown to black chitinous plates with ridged, segmented texture resembling beetle exoskeleton, including a large curved horn on the forehead, a shield-like plate over the shoulders and neck, and large oval wing-cover-like plates along the flanks and back.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like head in profile with dense brown fur, a lighter tan muzzle, a black nose at the tip, a small dark brown eye, and a closed mouth with slight fur around the jaws",
      "where": "at the front of the body, facing to the right"
    },
    {
      "part": "horns",
      "looks_like": "single large glossy black horn curving upward and forward, with two small pointed side prongs near the tip and a bulbous base where it meets the fur, resembling a rhinoceros beetle horn",
      "where": "projecting from the center of the forehead between the ears"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears covered in thick brown fur",
      "where": "on top of the head behind the horn"
    },
    {
      "part": "legs",
      "looks_like": "four thick, columnar legs covered in long shaggy brown fur, with darker fur on the outer side and lighter fur on the inner side, with shiny dark brown joint plates visible at the knees and ankles",
      "where": "under the body, two in front and two in back supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four broad paws with five toes each, covered in brown fur on top and bearing long curved light-tan claws",
      "where": "at the bottom of each leg in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "very short, stubby, furry tail covered in brown fur",
      "where": "at the rear of the body on the left side"
    },
    {
      "part": "plates",
      "looks_like": "multiple shiny hard chitinous plates in dark brown to glossy black with ridged and segmented surfaces; includes a large elongated oval plate with longitudinal ridges on the mid-flank, smaller triangular and oval plates on the back and rump, a large irregular shield plate with a pointed top on the shoulder and neck, and small curved plates wrapping the leg joints; a row of small oval dark holes is visible in the fur below the large flank plate",
      "where": "embedded in the fur over the shoulders, neck, sides, back, rump, chest, and around all four leg joints"
    },
    {
      "part": "markings",
      "looks_like": "fur color gradation from dark brown on the back, head and outer limbs to creamy off-white on the chest, throat and belly",
      "where": "over the entire body"
    }
  ],
  "attached_objects": [],
  "animals": ["bear", "beetle"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
